#include <cstdint>
#include <string>

struct tally
{
    std::string name;
    int64_t total{ 0 };
};

extern "C" int32_t tally_create(const char* name, tally** out)
{
    if (!name || !*name || !out) return 1;
    *out = new tally{ name, 0 };
    return 0;
}

extern "C" void tally_destroy(tally* t) { delete t; }

extern "C" int32_t tally_add(tally* t, int32_t amount)
{
    if (!t) return 1;
    t->total += amount;
    return 0;
}

extern "C" int32_t tally_value(const tally* t, int64_t* out)
{
    if (!t || !out) return 1;
    *out = t->total;
    return 0;
}

extern "C" int32_t tally_name_length(const tally* t, int32_t* out)
{
    if (!t || !out) return 1;
    *out = static_cast<int32_t>(t->name.size());
    return 0;
}

unitTests:
TEST("count up and down") { tally* t = nullptr; CHECK_EQ(tally_create("clicks", &t), 0); tally_add(t, 5); tally_add(t, -2); int64_t v = 0; CHECK_EQ(tally_value(t, &v), 0); CHECK_EQ(v, int64_t{ 3 }); tally_destroy(t); }
TEST("beyond 32 bits") { tally* t = nullptr; tally_create("big", &t); for (int i = 0; i < 3; ++i) tally_add(t, 2000000000); int64_t v = 0; tally_value(t, &v); CHECK_EQ(v, int64_t{ 6000000000 }); tally_destroy(t); }
TEST("name length") { tally* t = nullptr; tally_create("granite", &t); int32_t n = 0; CHECK_EQ(tally_name_length(t, &n), 0); CHECK_EQ(n, 7); tally_destroy(t); }
TEST("bad arguments") { tally* t = nullptr; CHECK_EQ(tally_create(nullptr, &t), 1); CHECK_EQ(tally_create("", &t), 1); CHECK_EQ(tally_create("x", nullptr), 1); int64_t v = 0; CHECK_EQ(tally_value(nullptr, &v), 1); CHECK_EQ(tally_add(nullptr, 1), 1); }
TEST("destroy null") { tally_destroy(nullptr); CHECK(true); }

